CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT COLLATE NOCASE, c1 VARCHAR(10) UNIQUE, c2 VARCHAR(10), c3 VARCHAR(10) UNIQUE, c4 TEXT);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(1e-7, NULL, x'', x'8ba1f41358', 2);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER DEFAULT 'd', c1 INT COLLATE NOCASE, c2, c3 TEXT CHECK(c3 IS NULL OR length(c3) < 40), c4 TEXT, ref INTEGER REFERENCES t0(id));
SELECT date('2000-01-01 12:34:56'), time('2000-01-01 12:34:56'), datetime('2000-01-01 12:34:56', '-1 month'), julianday('2000-01-01 12:34:56'), strftime('%s', '2000-01-01 12:34:56'), unixepoch('2000-01-01 12:34:56'), timediff('2024-03-01', '2023-01-15');
SELECT date(2451545.0), time(2451545.0), datetime(2451545.0, 'weekday 0'), julianday(2451545.0), strftime('%j %w %W', 2451545.0), unixepoch(2451545.0), timediff('2024-03-01', '2023-01-15');
SELECT date(1700000000), time(1700000000), datetime(1700000000, '+0 seconds'), julianday(1700000000), strftime('%f', 1700000000), unixepoch(1700000000), timediff('2024-03-01', '2023-01-15');
SELECT date(2451545.0), time(2451545.0), datetime(2451545.0, '+1 year'), julianday(2451545.0), strftime('%s', 2451545.0), unixepoch(2451545.0), timediff('2024-03-01', '2023-01-15');
SELECT date('1999-12-31T23:59:59.999'), time('1999-12-31T23:59:59.999'), datetime('1999-12-31T23:59:59.999', 'start of month'), julianday('1999-12-31T23:59:59.999'), strftime('%Y-%m-%d %H:%M:%S', '1999-12-31T23:59:59.999'), unixepoch('1999-12-31T23:59:59.999'), timediff('2024-03-01', '2023-01-15');
SELECT date('2000-01-01 12:34:56'), time('2000-01-01 12:34:56'), datetime('2000-01-01 12:34:56', '+1 year'), julianday('2000-01-01 12:34:56'), strftime('%j %w %W', '2000-01-01 12:34:56'), unixepoch('2000-01-01 12:34:56'), timediff('2024-03-01', '2023-01-15');
SELECT count(*), count(id), sum(id), total(id), avg(id), min(id), max(id), count(DISTINCT id) FROM t0;
SELECT id, count(*), group_concat(id) FROM (SELECT * FROM t0 ORDER BY id) GROUP BY id ORDER BY id;
